import{z as n,x as A,o as i,c as B,q as e,j as s,D as o,d as t,s as r,S as p,b as l}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"QK-Clip 梯度裁剪","description":"","frontmatter":{"title":"QK-Clip 梯度裁剪","date":"2026-09-27T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qk-clip.md","filePath":"llm/qk-clip.md","lastUpdated":1791063341000}'),m={name:"llm/qk-clip.md"};function d(_,a,g,C,h,K){const E=A("Mermaid");return i(),B("div",null,[a[2]||(a[2]=e('<h1 id="qk-clip-梯度裁剪" tabindex="-1">QK-Clip 梯度裁剪 <a class="header-anchor" href="#qk-clip-梯度裁剪" aria-label="Permalink to &quot;QK-Clip 梯度裁剪&quot;">​</a></h1><div class="epigraph"><p>训练崩溃不查学习率先查 QK 头：少数头的 logit 指数爆长，一剪头部权重，loss 尖峰当场熄火。</p><footer>—— 据 QK-Clip（万至千团队 Moonshot Kimi K2 技术报告 2025）；Grok-2 训练稳定性附记</footer></div><p><a href="/llm/schedule-free-optimizer">Schedule-Free 优化</a>管全局节奏，本课管致命局部：MoE 大模型训练中 1/1000 步的 loss spike。缺口是 <strong>QK-Clip</strong>——按头诊断注意力 logit 的发散，对越界头直接缩放 \\(W_Q\\) 或 \\(W_K\\)。它是把「稳定性工程」从全局梯度裁剪推进到头级手术的代表作。本课不做 Muon 系优化器稳定性的一般理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Muon 类优化器放宽了 Adam 的二阶矩自适应，梯度更新范数更「生猛」，MoE 大模型上出现低频 loss spike：某个注意力头持续输出巨大 QK 点积 → softmax 饱和 → 梯度路径异常 → loss 拉高数个点后缓慢恢复，且常在恢复后复发。全局梯度裁剪（grad clip）按范数一刀切，杀敌一百自损三千——问题只在个别头。缺口：<strong>定位并只剪病灶头</strong>。</p><p><span class="marginnote">术语翻译：QK logit = \\(q^\\top k/\\sqrt{d}\\) 的分值，进 softmax 前的数量级决定注意力集中度；logit 最大值 \\(\\approx\\|q\\|\\|k\\|/\\sqrt d\\)，故控制 \\(W_Q,W_K\\) 的谱范数即控制 logit 上限；α-threshold = 触发裁剪的 logit 阈值（Kimi K2 报告用 \\(\\tau_{max}\\approx 100\\)）。</span></p><p><span class="marginnote">数字实例：\\(d=128\\)，某头 \\(\\|q\\|=30\\)、\\(\\|k\\|=35\\)，logit 上限 \\(\\approx 30\\times35/11.3\\approx 93\\)——逼近 100 阈值。QK-Clip 对该头把 \\(W_K\\) 缩到 \\(\\gamma=0.5\\)，logit 上限即降半到 46，softmax 恢复分辨力；其余 63 个头不动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每步前向（或每 N 步）扫全部头：算 \\(\\tau_h=\\max(q^\\top k/\\sqrt d)\\)，超阈值则对该头执行 \\(W_K\\leftarrow\\gamma W_K\\)（或剪 \\(W_Q\\)），γ 按 \\(\\gamma_{target}/\\tau_h\\) 定，使缩放后 logit 恰落在目标内；阈值本身随训练动态调整（发散头消失后阈值收紧到更低水平）。关键性质：缩放 \\(W_K\\) 与 \\(W_Q\\) <strong>不改 softmax 输出的归一化结构</strong>之外的语义——它等价于给该头的温度乘 \\(1/\\gamma\\)，是注意力本来就有的自由度，故干预几乎无副作用。</p>',9)),(i(),s(p,null,{default:o(()=>[r(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%89%8D%E5%90%91%3A%20%E9%80%90%E5%A4%B4%E7%AE%97%20%CF%84_h%22%5D%20--%3E%20B%7B%22%CF%84_h%20%EF%BC%9E%20%E9%98%88%E5%80%BC%3F%22%7D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22%CE%B3%20%3D%20%E7%9B%AE%E6%A0%87%2F%CF%84_h%22%5D%0A%20%20C%20--%3E%20D%5B%22W_K%20%E2%86%90%20%CE%B3W_K%20(%E6%88%96%E5%89%AA%20W_Q)%22%5D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20E%5B%22%E8%AF%A5%E5%A4%B4%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20D%20--%3E%20F%5B%22logit%20%E4%B8%8A%E9%99%90%20%3D%20%E7%9B%AE%E6%A0%87%E5%86%85%22%5D%0A%20%20E%20--%3E%20F%0A%20%20F%20--%3E%20G%5B%22%E7%BB%A7%E7%BB%AD%E8%AE%AD%E7%BB%83%2C%20%E4%B8%8B%E6%AD%A5%E5%A4%8D%E6%A3%80%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,[l("span",{class:"marginnote"},"直觉类比：一屋子话筒（注意力头）里有一支啸叫（logit 爆长），调音台的全局推子（grad clip）一刀拉低全场音量——演出没法听了；QK-Clip 是找到啸叫的那支话筒把它的增益旋钮拧小半格，演出继续。")],-1)),a[4]||(a[4]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=l("p",null,[t("为什么发作在 QK 而不是 V/输出投影：softmax 对 logit 是指数敏感的，\\(W_QW_K\\) 的乘积结构使两个矩阵的范数"),l("strong",null,"相乘"),t("放大（各长 30% 则 logit 翻 1.7 倍），而 V/输出投影只线性放大。为什么全局裁剪失效：spike 的梯度异常是"),l("strong",null,"结果"),t("不是原因，等它传回来时全局范数早已被少数层污染，一刀切的裁剪破坏所有健康层的更新节奏。QK-Clip 在前向即拦截——病根暴露在 logit 上，治疗落在权重上，诊断与治疗同址。阈值自适应的逻辑：初始阈值抓恶性发散，训练稳定后阈值下调抓「慢性高温」，把病消灭在发烧前。")],-1)),(i(),s(p,null,{default:o(()=>[r(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E4%B8%BA%E4%BD%95%20QK%20%E5%85%88%E7%88%86%3F%22%7D%20--%3E%20R%5B%22W_Q%C2%B7W_K%20%E8%8C%83%E6%95%B0%E7%9B%B8%E4%B9%98%22%5D%0A%20%20R%20--%3E%20S%5B%2230%25%20%E5%A2%9E%E9%95%BF%20%E2%86%92%20logit%20%C3%971.7%22%5D%0A%20%20S%20--%3E%20T%5B%22softmax%20%E6%8C%87%E6%95%B0%E7%BA%A7%E6%95%8F%E6%84%9F%22%5D%0A%20%20U%7B%22%E4%B8%BA%E4%BD%95%E4%B8%8D%E8%A3%81%E5%85%A8%E5%B1%80%3F%22%7D%20--%3E%20V%5B%22%E6%A2%AF%E5%BA%A6%E5%BC%82%E5%B8%B8%E6%98%AF%E7%BB%93%E6%9E%9C%E9%9D%9E%E5%8E%9F%E5%9B%A0%22%5D%0A%20%20V%20--%3E%20W%5B%22%E4%B8%80%E5%88%80%E5%88%87%E6%AF%81%E5%81%A5%E5%BA%B7%E5%B1%82%E8%8A%82%E5%A5%8F%22%5D%0A%20%20T%20--%3E%20X%5B%22%E5%89%8D%E5%90%91%E6%8B%A6%E6%88%AA%20%2B%20%E5%A4%B4%E7%BA%A7%E6%89%8B%E6%9C%AF%22%5D%0A%20%20W%20--%3E%20X%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=e('<p><span class="marginnote">常见误区：见到 spike 就降学习率重训——低频 spike 的根因是结构性（个别头动力学），降 LR 只是把发作推迟；另一误区是剪 V 或输出投影——它们对 softmax 无影响，logit 该爆还爆，白剪。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>QK-Clip 管「注意力 logit 发散」这一类 spike；MoE 的路由震荡、优化器二阶矩失配、数据异常 batch 引发的 spike 走各自的路（路由熵正则、optimizer 状态回滚、数据回放过滤）。阈值是超参：过松漏抓、过紧误剪健康头的表达自由度——Kimi K2 报告的经验是「抓大放小」逐步收紧。与 <a href="/llm/logit-softcap">logit 软上限</a>的分工：软上限在<strong>推理/输出</strong>层给 logit 封顶（tanh 式），QK-Clip 在<strong>训练</strong>层做权重手术——一个是运行时护栏，一个是发育期正畸。适用性：Muon/MoE 大模型是重灾区，稠密 AdamW 模型多数用不上，但头级监控的诊断价值普适。</p><p><span class="marginnote">直觉类比：QK-Clip 与软上限的关系像「正畸 vs 护齿套」——正畸（剪权重）在发育期把牙列排齐，一劳永逸；护齿套（软上限）比赛时戴上防止磕碰，随时可摘。训练崩溃要正畸，推理越界装护齿。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>logit 上限 \\(\\propto\\|W_Q\\|\\|W_K\\|\\)，少数头乘积爆长即 spike 根因。</li><li>头级诊断 + 缩 \\(W_K/W_Q\\)，等价于调该头温度，副作用近零。</li><li>全局梯度裁剪治标伤好层；阈值自适应抓大放小。</li><li>出处：Kimi K2 技术报告（QK-Clip）2025；Grok-2 训练稳定性附记。</li></ul>',6))])}const u=n(m,[["render",d]]);export{f as __pageData,u as default};
